import{_ as e,o as a,c as t,a2 as i}from"./chunks/framework.Wk4ah3nE.js";const g=JSON.parse('{"title":"Hotplug and NUMA","description":"Why Proxmox VM Autoscale needs hotplug and NUMA to change a running VM, what applies live, what needs a reboot, and what auto_configure_hotplug changes on your guests.","frontmatter":{"title":"Hotplug and NUMA","description":"Why Proxmox VM Autoscale needs hotplug and NUMA to change a running VM, what applies live, what needs a reboot, and what auto_configure_hotplug changes on your guests.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/hotplug.html"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/hotplug.html"}],["meta",{"property":"og:title","content":"Hotplug and NUMA"}],["meta",{"property":"og:description","content":"Why Proxmox VM Autoscale needs hotplug and NUMA to change a running VM, what applies live, what needs a reboot, and what auto_configure_hotplug changes on your guests."}]]},"headers":[],"relativePath":"guide/hotplug.md","filePath":"guide/hotplug.md","lastUpdated":null}'),n={name:"guide/hotplug.md"};function o(l,s,h,r,p,d){return a(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="hotplug-and-numa" tabindex="-1">Hotplug and NUMA <a class="header-anchor" href="#hotplug-and-numa" aria-label="Permalink to &quot;Hotplug and NUMA&quot;">​</a></h1><p>Whether a scaling action takes effect immediately or waits for the next reboot is decided entirely by two guest settings. This page explains which, why, and what the service does about them.</p><h2 id="the-two-settings" tabindex="-1">The two settings <a class="header-anchor" href="#the-two-settings" aria-label="Permalink to &quot;The two settings&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vmi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -hotplug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cpu,memory,network,disk,usb</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vmi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -numa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div><p>Or in the web UI: <strong>VM → Options → Hotplug</strong> and <strong>VM → Hardware → Processors → Enable NUMA</strong>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Enables</th><th>Applies without reboot?</th></tr></thead><tbody><tr><td><code>hotplug: cpu</code></td><td>Adding/removing <strong>vCPUs</strong> on a running guest</td><td>Yes, the hotplug flag itself does</td></tr><tr><td><code>hotplug: memory</code></td><td>Memory changes on a running guest</td><td>Yes</td></tr><tr><td><code>numa: 1</code></td><td>Memory hotplug to actually function</td><td><strong>No</strong> — needs a guest reboot</td></tr></tbody></table><p>The trap is the last row. NUMA is part of the virtual machine topology, so turning it on does nothing until the guest is power-cycled. A VM with <code>hotplug: memory</code> but <code>numa: 0</code> looks configured and is not.</p><h2 id="what-applies-live" tabindex="-1">What applies live <a class="header-anchor" href="#what-applies-live" aria-label="Permalink to &quot;What applies live&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Change</th><th>Live with hotplug + NUMA</th><th>Otherwise</th></tr></thead><tbody><tr><td><strong>vCPU count</strong> (<code>-vcpus</code>)</td><td>Yes</td><td>n/a</td></tr><tr><td><strong>Core count</strong> (<code>-cores</code>)</td><td><strong>No — always needs a reboot</strong></td><td>Needs a reboot</td></tr><tr><td><strong>RAM</strong> (<code>-balloon</code>)</td><td>Yes</td><td>n/a</td></tr><tr><td><strong>RAM</strong> (<code>-memory</code>)</td><td>Needs a reboot</td><td>Needs a reboot</td></tr></tbody></table><p><code>cores</code> is the number of CPUs the virtual motherboard has sockets for; <code>vcpus</code> is how many of them are plugged in right now. Only the second can change on a running guest, and it can never exceed the first.</p><h2 id="how-the-service-uses-this" tabindex="-1">How the service uses this <a class="header-anchor" href="#how-the-service-uses-this" aria-label="Permalink to &quot;How the service uses this&quot;">​</a></h2><h3 id="scaling-cpu-up" tabindex="-1">Scaling CPU up <a class="header-anchor" href="#scaling-cpu-up" aria-label="Permalink to &quot;Scaling CPU up&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if running and hotplug:cpu</span></span>
<span class="line"><span>    if vcpus &lt; cores      → qm set -vcpus (vcpus + 1)          # live</span></span>
<span class="line"><span>    else                  → qm set -cores (cores + 1)          # needs reboot</span></span>
<span class="line"><span>                            qm set -vcpus (vcpus + 1)          # live, warned</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>    qm set -cores, qm set -vcpus                               # warning logged</span></span></code></pre></div><p>So the first few scale-ups on a guest with headroom (say 4 cores, 2 vCPUs) are genuinely live. Once vCPUs catch up with cores, each further step raises the core count too — and that part only materialises after a reboot. The log says so explicitly:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WARNING] VM 101: Increased cores to 5 (requires reboot for full effect)</span></span>
<span class="line"><span>          and vCPUs to 5 (hotplug applied).</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Give guests headroom in <code>cores</code></p><p>Provision a guest with more <code>cores</code> than it needs and fewer <code>vcpus</code>, e.g. <code>cores: 8, vcpus: 2</code>. Every scale-up inside that range is fully live, and you never hit the reboot boundary.</p></div><h3 id="scaling-cpu-down" tabindex="-1">Scaling CPU down <a class="header-anchor" href="#scaling-cpu-down" aria-label="Permalink to &quot;Scaling CPU down&quot;">​</a></h3><p>vCPUs are reduced first, which takes effect immediately. The core count is then also reduced, but only when it would stay at or above both the new vCPU count and <code>min_cores</code>. That part waits for a reboot.</p><div class="warning custom-block"><p class="custom-block-title">CPU hot-unplug depends on the guest OS</p><p>Removing a vCPU is far less reliable than adding one. Linux generally copes; some workloads pinned to a CPU do not; Windows guests frequently refuse. QEMU accepts the command either way and the service logs success. Verify with <code>nproc</code> inside a guest you care about.</p></div><h3 id="scaling-ram" tabindex="-1">Scaling RAM <a class="header-anchor" href="#scaling-ram" aria-label="Permalink to &quot;Scaling RAM&quot;">​</a></h3><p>With hotplug <strong>and</strong> NUMA on a running guest, the service sets the <strong>balloon</strong> value:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vmi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -balloon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4096</span></span></code></pre></div><p>The balloon driver inside the guest inflates or deflates to reach the target, so memory changes without a reboot. In every other case the service falls back to <code>-memory</code>, which only applies on next boot, and logs a warning saying so.</p><div class="warning custom-block"><p class="custom-block-title">The balloon driver has to be present and working</p><p>Ballooning needs <code>virtio_balloon</code> in the guest. Without it — most bare Windows installs before the VirtIO drivers are installed, some minimal container-style images — the command succeeds at the QEMU level and nothing happens inside the guest. Reclaiming memory from a guest that is genuinely using it can also drive it into swap or trigger the OOM killer.</p></div><h3 id="why-min-ram-mb-should-stay-at-1024" tabindex="-1">Why <code>min_ram_mb</code> should stay at 1024 <a class="header-anchor" href="#why-min-ram-mb-should-stay-at-1024" aria-label="Permalink to &quot;Why \`min_ram_mb\` should stay at 1024&quot;">​</a></h3><p>NUMA-enabled guests behave badly with very little memory; the shipped config sets <code>min_ram_mb: 1024</code> specifically for that. The step size is 512 MB, so a floor of 1024 also keeps the scale-down path from landing on awkward values.</p><h2 id="auto-configure-hotplug" tabindex="-1"><code>auto_configure_hotplug</code> <a class="header-anchor" href="#auto-configure-hotplug" aria-label="Permalink to &quot;\`auto_configure_hotplug\`&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auto_configure_hotplug</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # default</span></span></code></pre></div><p>When enabled, the first time the service handles a VM it inspects <code>qm config</code> and, if hotplug or NUMA is missing, issues:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vmi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -hotplug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cpu,memory,network,disk,usb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -numa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div><p>Then it logs:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[INFO] VM 101: Enabling hotplug for cpu,memory,network,disk,usb</span></span>
<span class="line"><span>[INFO] VM 101: Enabling NUMA for memory hotplug support</span></span>
<span class="line"><span>[INFO] VM 101: Hotplug configuration updated.</span></span>
<span class="line"><span>       Note: NUMA changes require a VM restart to take effect.</span></span></code></pre></div><h3 id="what-to-know-before-leaving-it-on" tabindex="-1">What to know before leaving it on <a class="header-anchor" href="#what-to-know-before-leaving-it-on" aria-label="Permalink to &quot;What to know before leaving it on&quot;">​</a></h3><ul><li><strong>It modifies your VM configuration without asking.</strong> On a fleet you did not build yourself, that may not be welcome.</li><li><strong>It enables hotplug for <code>network,disk,usb</code> too</strong>, not just CPU and memory. That is broader than the autoscaler needs.</li><li><strong>NUMA will not work until you reboot the guest.</strong> Until then memory scaling silently falls back to <code>-memory</code> + reboot. The service tells you once, in the log, at the moment it makes the change.</li><li><strong>It runs once per VM per service lifetime.</strong> After the fix that caches VM managers across cycles, this is a single check at startup rather than two extra <code>qm config</code> calls per VM on every poll.</li><li><strong>Failures are non-fatal.</strong> If <code>qm set</code> fails the service logs a warning and carries on with whatever the guest currently supports.</li></ul><p>Set it to <code>false</code> if you would rather configure guests deliberately:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auto_configure_hotplug</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><h2 id="verifying-a-guest-is-genuinely-live-scalable" tabindex="-1">Verifying a guest is genuinely live-scalable <a class="header-anchor" href="#verifying-a-guest-is-genuinely-live-scalable" aria-label="Permalink to &quot;Verifying a guest is genuinely live-scalable&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On the node</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 101</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;hotplug|numa|cores|vcpus|memory|balloon&#39;</span></span></code></pre></div><p>You want to see <code>hotplug:</code> containing both <code>cpu</code> and <code>memory</code>, and <code>numa: 1</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Inside the guest — has it been rebooted since numa was enabled?</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lscpu</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> numa</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dmesg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> balloon</span></span></code></pre></div><p>If <code>numa: 1</code> is in the VM config but <code>lscpu</code> shows no NUMA node, the guest has not been rebooted since the change and memory hotplug is not actually available yet.</p>`,41)])])}const u=e(n,[["render",o]]);export{g as __pageData,u as default};
